@Override
public PoolResponse createPool(CreatePoolRequest request) {
    String fingerprint = structuredFingerprint(Operation.CREATE_POOL, request.poolId(),
            request.operator(), poolParams(request));
    return runIdempotent(request.requestId(), Operation.CREATE_POOL, fingerprint,
            PoolResponse.class, () -> {
                if (rotationPoolRepository.findPoolById(request.poolId()).isPresent()) {
                    throw new ApiException(HttpStatus.CONFLICT, "pool already exists: " + request.poolId());
                }
                // 成员公告号唯一性
                Set<String> seen = new HashSet<>();
                for (var m : request.members()) {
                    if (!seen.add(m.campaignId())) {
                        throw new ApiException(HttpStatus.BAD_REQUEST, "duplicate member campaign: " + m.campaignId());
                    }
                    requireCampaign(m.campaignId()); // 404 if missing
                }
                RotationPool pool = new RotationPool(request.poolId(), POOL_VERSION, null, clock.millis());
                try {
